package me.memrii.app

import androidx.test.InstrumentationRegistry
import org.junit.Assert.*
import org.junit.Test
import org.json.JSONArray
import org.json.JSONObject
import java.io.File

/** Inputs/references are synthetic, generated by app/scripts/verify_audio_crop.py. */
@Suppress("DEPRECATION")
class AudioCropDecoderTest {
    private val instrumentation get() = InstrumentationRegistry.getInstrumentation()

    @Test
    fun testSyntheticReferences() {
        val inputs = File("/data/local/tmp/memrii-crop-fixtures")
        val cases = JSONArray(File(inputs, "cases.json").readText())
        val outputs = File(instrumentation.targetContext.getExternalFilesDir(null), "crop-comparison")
        outputs.mkdirs()
        val results = JSONArray()
        for (i in 0 until cases.length()) {
            val case = cases.getJSONObject(i)
            val result = JSONObject().put("name", case.getString("name"))
            val output = File(outputs, case.getString("name") + ".wav")
            try {
                AudioCropDecoder.crop(
                    File(inputs, case.getString("source")).path, output.path,
                    case.getLong("startUs"), case.getLong("endUs")
                )
                result.put("bytes", output.length())
            } catch (e: Exception) {
                result.put("error", e.toString())
            }
            results.put(result)
        }
        File(outputs, "results.json").writeText(results.toString(2))
        assertTrue("Some native crops failed: $results", (0 until results.length()).none { results.getJSONObject(it).has("error") })
    }

    @Test
    fun testFailureDoesNotPublishOrModifySource() {
        val folder = instrumentation.targetContext.cacheDir
        val source = File(folder, "invalid-crop.m4a").apply { writeBytes(byteArrayOf(1, 2, 3)) }
        val original = source.readBytes()
        val output = File(folder, "invalid-crop.wav")
        try {
            try {
                AudioCropDecoder.crop(source.path, output.path, 0, 1_000_000)
                fail("Malformed input must fail")
            } catch (_: Exception) {
                assertFalse(output.exists())
                assertTrue(source.readBytes().contentEquals(original))
            }
        } finally {
            source.delete()
            output.delete()
        }
    }

    @Test
    fun testRejectsOverwriteAndOutOfRange() {
        val source = File("/data/local/tmp/memrii-crop-fixtures/aac-16000-1.m4a")
        val original = source.readBytes()
        val output = File(instrumentation.targetContext.cacheDir, "out-of-range.wav")
        for (target in listOf(source, output)) {
            var rejected = false
            try {
                AudioCropDecoder.crop(source.path, target.path, 0, 10_000_000)
            } catch (_: IllegalArgumentException) {
                rejected = true
            }
            assertTrue("Invalid crop must fail", rejected)
            assertTrue("Source bytes must be preserved", source.readBytes().contentEquals(original))
            assertFalse(output.exists())
        }
    }
}
